#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "athena_internal.h"
#include "sf_buf.h"
static bool prefix_ci(const char*s,const char*p){while(*p){char a=*s++,b=*p++;if(a>='a'&&a<='z')a-=32;if(b>='a'&&b<='z')b-=32;if(a!=b)return false;}return true;}
static bool starts_select(const char*s){while(*s==' '||*s=='\t'||*s=='\r'||*s=='\n')s++;return prefix_ci(s,"SELECT")||prefix_ci(s,"WITH");}
static void csvcell(FILE*f,const char*s,char d){bool quote=!s||strchr(s,d)||strchr(s,'"')||strchr(s,'\n')||strchr(s,'\r');if(quote)fputc('"',f);for(;s&&*s;s++){if(*s=='"')fputc('"',f);fputc(*s,f);}if(quote)fputc('"',f);}
DbQueryResult db_export_data(const char*target,const char*path,const char*format,const char*compression,bool header,const char*delimiter){if(compression&&strcmp(compression,"none"))return athena_fail("Athena export currently supports compression=none only");SfBuf q={0};if(starts_select(target))sf_buf_str(&q,target);else{if(!db_validate_identifier(target))return athena_fail("Invalid export table name");sf_buf_str(&q,"SELECT * FROM ");sf_buf_str(&q,target);}char*sql=sf_buf_take(&q);DbQueryResult rows=sql?athena_run(sql):athena_fail("Out of memory");free(sql);if(!rows.success)return rows;FILE*f=fopen(path,"wb");if(!f){db_free_result(&rows);return athena_fail("Could not open export destination");}if(!format||!strcmp(format,"json")){fputs(rows.json_structured?rows.json_structured:"[]",f);fputc('\n',f);}else if(!strcmp(format,"csv")||!strcmp(format,"tsv")){JsonValue*a=json_parse(rows.json_structured);char d=!strcmp(format,"tsv")?'\t':(delimiter&&*delimiter?*delimiter:',');if(!a||a->type!=JSON_ARRAY){json_free(a);fclose(f);db_free_result(&rows);return athena_fail("Could not format Athena results for export");}if(a->u.array.count&&a->u.array.items[0]->type==JSON_OBJECT){JsonValue*first=a->u.array.items[0];if(header){for(size_t c=0;c<first->u.object.count;c++){if(c)fputc(d,f);csvcell(f,first->u.object.keys[c],d);}fputc('\n',f);}for(size_t r=0;r<a->u.array.count;r++){JsonValue*o=a->u.array.items[r];for(size_t c=0;c<first->u.object.count;c++){if(c)fputc(d,f);const char*v=json_string_value(json_object_get(o,first->u.object.keys[c]));csvcell(f,v?v:"",d);}fputc('\n',f);}}json_free(a);}else{fclose(f);db_free_result(&rows);return athena_fail("Athena export supports json, csv, or tsv");}fclose(f);db_free_result(&rows);DbQueryResult out;memset(&out,0,sizeof(out));SfBuf md={0},js={0};sf_buf_printf(&md,"Exported Athena results to %s.",path);sf_buf_str(&js,"{\"status\":\"success\",\"engine\":\"athena\",\"path\":\"");sf_buf_json_escaped(&js,path);sf_buf_str(&js,"\"}");out.markdown_table=sf_buf_take(&md);out.json_structured=sf_buf_take(&js);out.success=out.markdown_table&&out.json_structured;return out;}
DbQueryResult db_import_data(const char*a,const char*b,const char*c,const char*d,bool e,const char*f,const char*g,bool h,bool i){(void)a;(void)b;(void)c;(void)d;(void)e;(void)f;(void)g;(void)h;(void)i;return athena_fail("Athena cannot upload local rows directly; upload data to S3 and create or update a Glue/Athena table");}
